    "title": {
      "type": "Text",
      "props": {
        "text": "Your 5-Week GRE Quant Study Blueprint",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "This study plan is designed to systematically cover all major GRE Quantitative Reasoning topics over four weeks, with a final week dedicated to full-length practice and consolidation."
      },
      "children": []
    },
    "context_card": {
      "type": "Card",
      "props": {},
      "children": [
        "context_stack"
      ]
    },
    "context_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "context_title",
        "context_body"
      ]
    },
    "context_title": {
      "type": "Text",
      "props": {
        "text": "Study Plan Context",
        "variant": "h2"
      },
      "children": []
    },
    "context_body": {
      "type": "Text",
      "props": {
        "text": "This plan starts on Friday, July 26, 2024. It assumes you have access to a primary GRE preparation resource and supplemental online question banks. Adjust the focus on sub-topics based on your personal strengths and weaknesses."
      },
      "children": []
    },
    "overview_title": {
      "type": "Text",
      "props": {
        "text": "Weekly Focus Overview",
        "variant": "h2"
      },
      "children": []
    },
    "overview_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "week",
            "label": "Week"
          },
          {
            "key": "dates",
            "label": "Dates"
          },
          {
            "key": "topic",
            "label": "Primary Topic"
          },
          {
            "key": "focus",
            "label": "Saturday Focus (3 hrs)"
          },
          {
            "key": "goal",
            "label": "End-of-Week Goal"
          }
        ],
        "rows": [
          {
            "week": "1",
            "dates": "Jul 26 - Aug 1",
            "topic": "Arithmetic",
            "focus": "Deep Dive: Fractions, Decimals, Percentages",
            "goal": "Master core number properties and calculations."
          },
          {
            "week": "2",
            "dates": "Aug 2 - Aug 8",
            "topic": "Algebra",
            "focus": "Word Problems & Systems of Equations",
            "goal": "Solve equations, inequalities, and functions efficiently."
          },
          {
            "week": "3",
            "dates": "Aug 9 - Aug 15",
            "topic": "Geometry",
            "focus": "Coordinate Geometry & 3D Shapes",
            "goal": "Understand spatial relationships and formulas."
          },
          {
            "week": "4",
            "dates": "Aug 16 - Aug 22",
            "topic": "Data Analysis",
            "focus": "Probability & Combinatorics",
            "goal": "Interpret data and calculate statistical measures."
          },
          {
            "week": "5",
            "dates": "Aug 23 - Aug 29",
            "topic": "Final Review",
            "focus": "In-depth Test 1 Error Analysis",
            "goal": "Build stamina and refine test-taking strategy."
          }
        ],
        "domain": "schedule",
        "preferredPresentation": "table"
      },
      "children": []
    },
    "schedule_title": {
      "type": "Text",
      "props": {
        "text": "Detailed Weekly Study Schedule",
        "variant": "h2"
      },
      "children": []
    },
    "week1_card": {
      "type": "Card",
      "props": {},
      "children": [
        "week1_stack"
      ]
    },
    "week1_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "week1_title",
        "week1_details"
      ]
    },
    "week1_title": {
      "type": "Text",
      "props": {
        "text": "Week 1: Arithmetic (July 26 - August 1)",
        "variant": "h3"
      },
      "children": []
    },
    "week1_details": {
      "type": "Text",
      "props": {
        "text": "- Friday (90 min): Number Properties, Integers, Divisibility Rules.\n- Saturday (3 hrs): Fractions, Decimals, Percentages, and Ratio/Proportion.\n- Monday (90 min): Exponents and Roots.\n- Tuesday (90 min): Rates and Work Problems.\n- Wednesday (90 min): General review of all Arithmetic topics.\n- Thursday (90 min): Timed quiz on Arithmetic and review mistakes."
      },
      "children": []
    },
    "week2_card": {
      "type": "Card",
      "props": {},
      "children": [
        "week2_stack"
      ]
    },
    "week2_stack": {
