    "week2_title": {
      "type": "Text",
      "props": {
        "text": "Week 2: Algebra (August 2 - August 8)",
        "variant": "h3"
      },
      "children": []
    },
    "week2_details": {
      "type": "Text",
      "props": {
        "text": "- Friday (90 min): Operations with Algebraic Expressions, Rules of Exponents.\n- Saturday (3 hrs): Solving Linear & Quadratic Equations, Systems of Equations, and Inequalities.\n- Monday (90 min): Functions and their properties.\n- Tuesday (90 min): Advanced Word Problems.\n- Wednesday (90 min): General review of all Algebra topics.\n- Thursday (90 min): Timed quiz on Algebra and error analysis."
      },
      "children": []
    },
    "week3_card": {
      "type": "Card",
      "props": {},
