    "week3_title": {
      "type": "Text",
      "props": {
        "text": "Week 3: Geometry (August 9 - August 15)",
        "variant": "h3"
      },
      "children": []
    },
    "week3_details": {
      "type": "Text",
      "props": {
        "text": "- Friday (90 min): Lines, Angles, Triangles, and Quadrilaterals.\n- Saturday (3 hrs): Circles, Polygons, and 3D Figures.\n- Monday (90 min): Coordinate Geometry.\n- Tuesday (90 min): Mixed Geometry problem-solving session.\n- Wednesday (90 min): General review of all Geometry topics.\n- Thursday (90 min): Timed quiz on Geometry and review mistakes."
      },
      "children": []
    },
    "week4_card": {
      "type": "Card",
