    "week4_title": {
      "type": "Text",
      "props": {
        "text": "Week 4: Data Analysis (August 16 - August 22)",
        "variant": "h3"
      },
      "children": []
    },
    "week4_details": {
      "type": "Text",
      "props": {
        "text": "- Friday (90 min): Statistics (Mean, Median, Mode, Range).\n- Saturday (3 hrs): Advanced Statistics and Probability.\n- Monday (90 min): Combinatorics.\n- Tuesday (90 min): Data Interpretation (Graphs, Charts, Tables).\n- Wednesday (90 min): General review of all Data Analysis topics.\n- Thursday (90 min): Timed quiz on Data Analysis and review errors."
      },
      "children": []
