    "week5_title": {
      "type": "Text",
      "props": {
        "text": "Week 5: Final Review & Practice Tests (August 23 - August 29)",
        "variant": "h3"
      },
      "children": []
    },
    "week5_details": {
      "type": "Text",
      "props": {
        "text": "- Friday (90 min): Take a full-length ETS POWERPREP Online Practice Test 1.\n- Saturday (3 hrs): Deep review of Test 1.\n- Monday (90 min): Targeted practice on weakest topics.\n- Tuesday (90 min): Take a second full-length Practice Test.\n- Wednesday (90 min): Review Test 2.\n- Thursday (90 min): Light review and rest."
      },
      "children": []
